        ('cross-docking', '/krɒs ˈdɒkɪŋ/', 'n', 'phương pháp phân phối trung chuyển không lưu kho', 'a logistics practice where cargo is unloaded from incoming transport and directly loaded into outbound trucks', 'Cross-docking eliminates inventory holding costs for perishable dairy goods.', 'Phương pháp trung chuyển không lưu kho loại bỏ chi phí tồn kho cho các sản phẩm bơ sữa tươi sống.', ['direct transfer'], ['cross-docking facility', 'cross-docking terminal'], 'Dock across directly to another truck'),
        ('demurrage', '/dɪˈmɜːrɪdʒ/', 'n', 'phí phạt lưu container tại cảng', 'a charge payable to the owner of a chartered ship in respect of failure to load or discharge within the time', 'The importer accrued thousands in demurrage fees due to delayed customs clearance.', 'Nhà nhập khẩu đã phát sinh hàng ngàn đô la phí lưu container do việc thông quan bị chậm trễ.', ['detention fee', 'storage charge'], ['demurrage charge', 'incur demurrage'], 'Demur = delay fine at dock'),
        ('bonded warehouse', '/ˈbɒndɪd ˈwɛərhaʊs/', 'n', 'kho ngoại quan (chưa đóng thuế)', 'a customs-controlled warehouse for the retention of imported goods until the duty owed is paid', 'Spirits and luxury watches remain stored in the bonded warehouse prior to re-export.', 'Rượu mạnh và đồng hồ xa xỉ vẫn được lưu giữ trong kho ngoại quan trước khi tái xuất khẩu.', ['customs warehouse'], ['bonded warehouse facility', 'store in bonded warehouse'], 'Bonded = held under customs security bond'),
