        ('drop-shipping', '/ˈdrɒpˌʃɪpɪŋ/', 'n', 'mô hình giao hàng thẳng từ xưởng', "a retail fulfillment method where a store doesn't keep the products it sells in stock", 'Young entrepreneurs launch online stores using drop-shipping to minimize initial inventory capital.', 'Các nhà khởi nghiệp trẻ mở cửa hàng trực tuyến dùng hình thức giao thẳng để giảm thiểu vốn tồn kho.', ['direct fulfillment'], ['drop-shipping business', 'drop-shipping supplier'], 'Drop directly to customer door'),
        ('backorder', '/ˈbækrɔːrdər/', 'n', 'đơn đặt hàng chờ bổ sung kho', "a retailer's order for a product that is temporarily out of stock with the supplier", 'The wildly popular gaming console went on backorder for six consecutive weeks.', 'Máy chơi game cực kỳ được ưa chuộng đã rơi vào tình trạng nhận đơn chờ hàng trong 6 tuần liên tiếp.', ['delayed order'], ['put on backorder', 'backorder status'], 'Back + order: waiting in the back'),
        ('SKU', '/ˌɛs keɪ ˈjuː/', 'n', 'mã đơn vị lưu kho (Stock Keeping Unit)', 'Stock Keeping Unit; a unique scannable bar code printed on product labels', 'The mega-mart catalog encompasses more than fifty thousand unique SKUs.', 'Danh mục của đại siêu thị bao gồm hơn năm mươi nghìn mã đơn vị lưu kho riêng biệt.', ['stock code', 'product identifier'], ['unique SKU', 'manage SKUs'], 'Stock Keeping Unit acronym'),
        ('RFID', '/ˌɑːr ɛf aɪ ˈdiː/', 'n', 'công nghệ nhận dạng tần số vô tuyến', 'Radio Frequency Identification; wireless technology tracking tags attached to objects', 'RFID sensors instantly scan whole pallet inventories without manual barcode pointing.', 'Cảm biến RFID quét tức thì toàn bộ pallet hàng hóa mà không cần soi từng mã vạch thủ công.', ['radio tracking'], ['RFID tag', 'RFID reader'], 'Radio Frequency ID'),
        ('3PL', '/ˌθriː piː ˈɛl/', 'n', 'dịch vụ logistics bên thứ ba', 'Third-Party Logistics; outsourcing of eCommerce logistics processes to an external provider', 'The apparel brand partnered with a nationwide 3PL provider for overnight deliveries.', 'Thương hiệu may mặc đã bắt tay với một công ty dịch vụ logistics bên thứ ba để giao hàng hỏa tốc qua đêm.', ['third-party logistics', 'fulfillment provider'], ['3PL provider', '3PL warehouse'], 'Third-Party Logistics'),
        ('lead time', '/ˈliːd taɪm/', 'n', 'thời gian thực hiện đơn hàng (từ đặt đến giao)', 'the time between the initiation and completion of a production or delivery process', 'Switching to regional component suppliers slashed assembly lead time from months to days.', 'Chuyển sang nhà cung ứng linh kiện trong khu vực đã rút ngắn thời gian lắp ráp từ hàng tháng xuống chỉ vài ngày.', ['cycle time', 'turnaround time'], ['shorten lead time', 'manufacturing lead time'], 'Lead time: time leading to arrival'),
        ('safety stock', '/ˈseɪfti stɒk/', 'n', 'lượng hàng dự trữ an toàn', 'an extra quantity of a good which is held in the warehouse to prevent stockouts', 'Unpredictable shipping delays forced retailers to maintain larger buffers of safety stock.', 'Sự chậm trễ vận tải khó lường buộc các nhà bán lẻ phải duy trì lượng hàng dự trữ an toàn lớn hơn.', ['buffer inventory', 'reserve stock'], ['calculate safety stock', 'safety stock level'], 'Safety + stock'),
